+	                          Value("\\x00\\x00\\x00a")));
+
+	// enums
+	vector<string> small_enum {"DUCK_DUCK_ENUM", "GOOSE"};
+	result.push_back(TestType(LogicalType::ENUM("small_enum", small_enum), "small_enum"));
+
+	vector<string> medium_enum;
